styles:
/* ==========================================
   医療痩身クリニック比較表
   横スクロール・左端固定・スマホ対応
========================================== */

.medical-table-scroll {
  position: relative;
  display: block;
  width: 100%;
  max-width: 100%;
  margin: 1.5em 0;
  padding: 0 0 8px;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: #c94a65 #f8e9ed;
}

.medical-table-scroll::-webkit-scrollbar {
  height: 8px;
}

.medical-table-scroll::-webkit-scrollbar-track {
  background: #f8e9ed;
  border-radius: 10px;
}

.medical-table-scroll::-webkit-scrollbar-thumb {
  background: #c94a65;
  border-radius: 10px;
}

.medical-table-scroll table {
  width: 1500px;
  min-width: 1500px;
  max-width: none;
  margin: 0;
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  font-size: 13px;
  line-height: 1.55;
}

.medical-table-scroll th,
.medical-table-scroll td {
  box-sizing: border-box;
  padding: 12px 10px;
  border-right: 1px solid #e1d8db;
  border-bottom: 1px solid #e1d8db;
  vertical-align: middle;
  text-align: center;
  white-space: normal;
  word-break: normal;
  overflow-wrap: break-word;
}

.medical-table-scroll thead th {
  color: #fff;
  font-weight: 700;
  background: #c94a65;
  border-top: 1px solid #e1d8db;
}

.medical-table-scroll tbody td {
  background: #fff;
}

.medical-table-scroll tbody tr:nth-child(even) td {
  background: #fff8fa;
}

/* 左端のクリニック列を固定 */
.medical-table-scroll tr > th:first-child {
  position: sticky;
  left: 0;
  z-index: 4;
  width: 200px;
  min-width: 200px;
  max-width: 200px;
  border-left: 1px solid #e1d8db;
  background: #fff4f7;
  box-shadow: 5px 0 8px rgba(70, 25, 40, 0.12);
}

.medical-table-scroll thead tr > th:first-child {
  z-index: 6;
  color: #fff;
  background: #a93651;
}

.medical-table-scroll tbody tr:nth-child(even) > th:first-child {
  background: #ffedf2;
}

/* 各列の幅 */
.medical-table-scroll th:nth-child(2),
.medical-table-scroll td:nth-child(2) {
  width: 230px;
}

.medical-table-scroll th:nth-child(3),
.medical-table-scroll td:nth-child(3) {
  width: 190px;
}

.medical-table-scroll th:nth-child(4),
.medical-table-scroll td:nth-child(4) {
  width: 150px;
}

.medical-table-scroll th:nth-child(5),
.medical-table-scroll td:nth-child(5) {
  width: 180px;
}

.medical-table-scroll th:nth-child(6),
.medical-table-scroll td:nth-child(6) {
  width: 230px;
}

.medical-table-scroll th:nth-child(7),
.medical-table-scroll td:nth-child(7) {
  width: 190px;
}

.medical-table-scroll th:nth-child(8),
.medical-table-scroll td:nth-child(8) {
  width: 180px;
}

/* クリニック名 */
.medical-table-scroll .clinic-name {
  display: block;
  margin-bottom: 9px;
  color: #333;
  font-weight: 700;
  line-height: 1.5;
}

/* 詳細ボタン */
.medical-table-scroll .corg-inline-btn {
  display: inline-block !important;
  width: auto !important;
  max-width: 100%;
  margin: 0 !important;
  writing-mode: horizontal-tb !important;
}

.medical-table-scroll .corg-inline-btn a {
  display: inline-block !important;
  box-sizing: border-box;
  width: auto !important;
  min-width: 108px;
  max-width: 100%;
  padding: 7px 10px !important;
  color: #fff !important;
  font-size: 11px !important;
  font-weight: 700;
  line-height: 1.3 !important;
  text-align: center;
  text-decoration: none !important;
  white-space: nowrap !important;
  writing-mode: horizontal-tb !important;
  background: #d94762;
  border: 0;
  border-radius: 5px;
}

.medical-table-scroll .corg-inline-btn a:hover {
  color: #fff !important;
  opacity: 0.88;
}

/* ==========================================
   スマホ
========================================== */

@media screen and (max-width: 767px) {

  .medical-table-scroll {
    width: 100%;
    max-width: 100%;
    margin: 1.25em 0;
    padding-bottom: 8px;
  }

  .medical-table-scroll table {
    width: 1120px;
    min-width: 1120px;
    font-size: 11px;
    line-height: 1.45;
  }

  .medical-table-scroll th,
  .medical-table-scroll td {
    padding: 9px 7px;
  }

  /* スマホの固定列 */
  .medical-table-scroll tr > th:first-child {
    width: 140px;
    min-width: 140px;
    max-width: 140px;
    font-size: 11px;
    box-shadow: 4px 0 7px rgba(70, 25, 40, 0.14);
  }

  .medical-table-scroll .clinic-name {
    margin-bottom: 7px;
    line-height: 1.4;
  }

  .medical-table-scroll .corg-inline-btn a {
    min-width: 94px;
    padding: 6px 5px !important;
    font-size: 10px !important;
  }

  /* スマホの各列幅 */
  .medical-table-scroll th:nth-child(2),
  .medical-table-scroll td:nth-child(2) {
    width: 175px;
  }

  .medical-table-scroll th:nth-child(3),
  .medical-table-scroll td:nth-child(3) {
    width: 150px;
  }

  .medical-table-scroll th:nth-child(4),
  .medical-table-scroll td:nth-child(4) {
    width: 115px;
  }

  .medical-table-scroll th:nth-child(5),
  .medical-table-scroll td:nth-child(5) {
    width: 140px;
  }

  .medical-table-scroll th:nth-child(6),
  .medical-table-scroll td:nth-child(6) {
    width: 180px;
  }

  .medical-table-scroll th:nth-child(7),
  .medical-table-scroll td:nth-child(7) {
    width: 155px;
  }

  .medical-table-scroll th:nth-child(8),
  .medical-table-scroll td:nth-child(8) {
    width: 145px;
  }
}

p.dummy a {
    color: #0066cc !important;
    text-decoration: underline !important;
}
